// static
bool HeartbeatServiceStubDispatch::AcceptWithResponder(
    HeartbeatService* impl,
    mojo::Message* message,
    std::unique_ptr<mojo::MessageReceiverWithStatus> responder) {
  [[maybe_unused]] const bool message_is_sync =
      message->has_flag(mojo::Message::kFlagIsSync);
  [[maybe_unused]] const uint64_t request_id = message->request_id();
  switch (message->header()->name) {
    case internal::kHeartbeatService_Register_Name: {

      internal::HeartbeatService_Register_Params_Data* params =
          reinterpret_cast<
              internal::HeartbeatService_Register_Params_Data*>(
                  message->mutable_payload());
      
      
      // Validation for HeartbeatService.0
      bool success = true;
      ServiceName p_name{};
      HeartbeatServiceArgumentPtr p_argument{};
      ::mojo::PendingReceiver<Pacemaker> p_receiver{};
      HeartbeatService_Register_ParamsDataView input_data_view(params, message);
      
      if (success && !input_data_view.ReadName(&p_name))
        success = false;
      if (success && !input_data_view.ReadArgument(&p_argument))
        success = false;
      if (success) {
        p_receiver =
            input_data_view.TakeReceiver<decltype(p_receiver)>();
      }
      if (!success) {
        ReportValidationErrorForMessage(
            message,
            mojo::internal::VALIDATION_ERROR_DESERIALIZATION_FAILED,
            HeartbeatService::Name_, 0, false);
        return false;
      }
      HeartbeatService::RegisterCallback callback =
          HeartbeatService_Register_ProxyToResponder::CreateCallback(
              *message, std::move(responder));
      // A null |impl| means no implementation was bound.
      DCHECK(impl);
      impl->Register(        
        std::move(p_name), 
        std::move(p_argument), 
        std::move(p_receiver), std::move(callback));
      return true;
    }
  }
  return false;
}
